package app.noir.mobile;

import android.app.*;
import android.os.*;
import android.content.Intent;
import android.graphics.Color;
import android.view.*;
import android.widget.*;
import org.json.*;
import java.util.*;
import java.util.concurrent.*;

/** Commands the paired PC; the phone never receives TorBox keys or CDN URLs. */
public final class PcDownloadsActivity extends Activity {
    final ExecutorService requests=Executors.newSingleThreadExecutor();
    DataStore data; LinearLayout body; TextView feedback; String itemId="",releaseId="",requestId=""; boolean season=false,busy=false; int revision=0;
    ScrollView queueScroll;boolean queueMode=false,foreground=false;final Handler queueHandler=new Handler(Looper.getMainLooper());final Runnable queueTick=new Runnable(){public void run(){if(foreground&&queueMode&&!busy)loadQueue();if(foreground)queueHandler.postDelayed(this,5000);}};
    final Map<String,LinearLayout> queueRows=new LinkedHashMap<>();final Map<String,TextView> queueLabels=new HashMap<>();final Map<String,ProgressBar> queueProgress=new HashMap<>();final Map<String,String> queueStates=new HashMap<>();final Map<String,LinearLayout> queueActions=new HashMap<>();
    JSONObject selectedRelease; JSONArray files;final Set<String> expandedQualities=new HashSet<>();
    @Override public void onCreate(Bundle b){super.onCreate(b);data=NoirApp.data;itemId=getIntent().getStringExtra("id");if(itemId==null)itemId="";season=getIntent().getBooleanExtra("season",false);if(b!=null){releaseId=b.getString("release","");requestId=b.getString("request","");try{files=new JSONArray(b.getString("files","[]"));}catch(Exception ignored){}}if(files!=null&&!releaseId.isEmpty())showFiles();else if(itemId.isEmpty())queue();else search();}
    @Override public void onSaveInstanceState(Bundle b){b.putString("release",releaseId);b.putString("request",requestId);if(files!=null)b.putString("files",files.toString());super.onSaveInstanceState(b);}
    int dp(int n){return Math.round(n*getResources().getDisplayMetrics().density);}
    TextView text(String s,int size){TextView t=new TextView(this);t.setText(s);t.setTextSize(size);t.setTextColor(MainActivity.WHITE);t.setPadding(0,dp(8),0,dp(8));return t;}
    Button button(String s,Runnable action){Button b=new Button(this);b.setText(s);b.setAllCaps(false);b.setTextSize(14);b.setMinimumHeight(dp(48));b.setTextColor(MainActivity.WHITE);b.setBackground(MainActivity.bg(MainActivity.PANEL,dp(10)));b.setOnClickListener(v->action.run());LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,-2);p.setMargins(0,dp(8),0,dp(8));b.setLayoutParams(p);return b;}
    void page(String title){revision++;LinearLayout root=new LinearLayout(this);root.setOrientation(LinearLayout.VERTICAL);root.setBackgroundColor(MainActivity.BLACK);root.setFitsSystemWindows(true);root.setPadding(dp(16),dp(12),dp(16),dp(12));setContentView(root);LinearLayout header=new LinearLayout(this);header.setGravity(Gravity.CENTER_VERTICAL);Button back=button("‹",this::finish);back.setContentDescription("Back");header.addView(back,new LinearLayout.LayoutParams(dp(48),dp(48)));TextView heading=text(title,22);heading.setPadding(dp(12),dp(8),0,dp(8));header.addView(heading,new LinearLayout.LayoutParams(0,-2,1));root.addView(header);ScrollView scroll=new ScrollView(this);queueScroll=scroll;body=new LinearLayout(this);body.setOrientation(LinearLayout.VERTICAL);scroll.addView(body);root.addView(scroll,new LinearLayout.LayoutParams(-1,0,1));feedback=text("",13);root.addView(feedback);}
    interface Work {JSONObject run()throws Exception;}
    interface Result {void accept(JSONObject data)throws Exception;}
    void request(String message,Work work,Result result){if(busy)return;busy=true;feedback.setText(message);int view=revision;requests.execute(()->{try{JSONObject value=work.run();runOnUiThread(()->{busy=false;if(isFinishing()||view!=revision)return;try{feedback.setText("");result.accept(value);}catch(Exception e){feedback.setText("Couldn't read the PC response. Update Noir on both devices.");}});}catch(Exception e){runOnUiThread(()->{busy=false;if(!isFinishing()&&view==revision)feedback.setText(e.getMessage());});}});}
    void search(){queueMode=false;page(season?"Download season to PC":"Download to PC");body.addView(text("Choose a release from AIOStreams, then its files from TorBox. Your PC must be open and connected.",14));body.addView(button("Find / refresh releases",this::loadReleases));loadReleases();}
    void loadReleases(){request("Finding releases…",()->data.pcRequest("/v1/pc-downloads/search/"+itemId+"?season="+season,null),r->{
        JSONArray all=r.getJSONArray("choices");body.removeAllViews();LinearLayout toolbar=new LinearLayout(this);body.addView(toolbar);Button refresh=button("Refresh releases",this::loadReleases);LinearLayout.LayoutParams refreshLayout=new LinearLayout.LayoutParams(0,dp(48),1);refreshLayout.setMargins(0,dp(8),dp(8),dp(8));toolbar.addView(refresh,refreshLayout);
        for(JSONObject source:DataStore.objects(r.optJSONArray("sources")))if(source.optString("state").equals("Failed"))body.addView(text(source.optString("source")+" · "+source.optString("message"),13));
        if(season&&all.length()>0)body.addView(button("Plan missing episodes",()->loadPlan(all)));
        LinearLayout list=new LinearLayout(this);list.setOrientation(LinearLayout.VERTICAL);
        android.content.SharedPreferences prefs=getSharedPreferences("release-filters",MODE_PRIVATE);
        LinearLayout filters=new LinearLayout(this);filters.setOrientation(LinearLayout.VERTICAL);filters.setVisibility(View.GONE);
        Button filter=button("Filter releases",()->filters.setVisibility(filters.getVisibility()==View.GONE?View.VISIBLE:View.GONE));LinearLayout.LayoutParams filterLayout=new LinearLayout.LayoutParams(0,dp(48),1);filterLayout.setMargins(0,dp(8),0,dp(8));toolbar.addView(filter,filterLayout);body.addView(filters);
        List<String> qualities=new ArrayList<>();qualities.add("All");List<String> languages=new ArrayList<>();languages.add("All");
        for(JSONObject c:DataStore.objects(all)){String q=c.optString("resolution");if(!q.isEmpty()&&!qualities.contains(q))qualities.add(q);for(String lang:c.optString("languages","Unknown").split(" / "))if(!lang.isEmpty()&&!languages.contains(lang))languages.add(lang);}
        Spinner quality=filterSpinner(filters,"Quality",qualities,prefs.getString("quality","All"));
        Spinner language=filterSpinner(filters,"Audio language",languages,prefs.getString("language","All"));
        List<String> sizes=Arrays.asList("Any size","1 GB","2 GB","4 GB","8 GB","16 GB");Spinner maximum=filterSpinner(filters,"Maximum release size · packs and unknown sizes stay visible",sizes,prefs.getString("size","Any size"));
        Switch ready=new Switch(this);ready.setText("Ready on TorBox only");ready.setTextColor(MainActivity.WHITE);ready.setChecked(prefs.getBoolean("ready",false));filters.addView(ready);
        TextView count=text("",14);body.addView(count);body.addView(list);
        Runnable render=()->{
            String q=quality.getSelectedItem().toString(),lang=language.getSelectedItem().toString(),size=maximum.getSelectedItem().toString();long limit=size.equals("Any size")?0:Long.parseLong(size.split(" ")[0])*1073741824L;
            prefs.edit().putString("quality",q).putString("language",lang).putString("size",size).putBoolean("ready",ready.isChecked()).apply();
            list.removeAllViews();List<JSONObject> visible=new ArrayList<>();int sources=0;for(JSONObject c:DataStore.objects(all)){
                if(!q.equals("All")&&!q.equals(c.optString("resolution")))continue;
                if(!lang.equals("All")&&!c.optString("languages","Unknown").toLowerCase(Locale.ROOT).contains(lang.toLowerCase(Locale.ROOT)))continue;
                if(ready.isChecked()&&!c.optString("cacheStatus").equals("Ready"))continue;
                if(limit>0&&c.optLong("size")>limit&&!c.optString("sizeKind").equals("Pack"))continue;
                visible.add(c);sources+=Math.max(1,c.optInt("sourceEntries",1));
            }
            count.setText(visible.size()+" of "+all.length()+" distinct releases · "+sources+" source entries");
            List<JSONObject> suggested=new ArrayList<>(visible);suggested.sort((left,right)->Boolean.compare(right.optString("cacheStatus").equals("Ready"),left.optString("cacheStatus").equals("Ready")));
            list.addView(text("Suggested choices",20));for(JSONObject c:suggested.subList(0,Math.min(3,suggested.size())))list.addView(releaseCard(c));
            Map<String,List<JSONObject>> groups=new LinkedHashMap<>();for(JSONObject c:visible){String groupQuality=c.optString("resolution");if(groupQuality.isEmpty())groupQuality="Quality unknown";if(groupQuality.equals("2160p"))groupQuality="4K";groups.computeIfAbsent(groupQuality,k->new ArrayList<>()).add(c);}
            list.addView(text("All releases",20));for(Map.Entry<String,List<JSONObject>> group:groups.entrySet()){
                LinearLayout entries=new LinearLayout(this);entries.setOrientation(LinearLayout.VERTICAL);entries.setVisibility(View.GONE);
                int groupSources=0;for(JSONObject c:group.getValue())groupSources+=Math.max(1,c.optInt("sourceEntries",1));
                Button toggle=button(group.getKey()+" · "+group.getValue().size()+" releases · "+groupSources+" source entries  ▾",()->{if(entries.getChildCount()==0)appendReleases(entries,group.getValue(),0);boolean open=entries.getVisibility()==View.GONE;entries.setVisibility(open?View.VISIBLE:View.GONE);if(open)expandedQualities.add(group.getKey());else expandedQualities.remove(group.getKey());});list.addView(toggle);list.addView(entries);if(expandedQualities.contains(group.getKey())){appendReleases(entries,group.getValue(),0);entries.setVisibility(View.VISIBLE);}
            }
            if(visible.isEmpty())list.addView(text("No choices match. Reset filters to see all releases.",16));
        };
        filters.addView(button("Reset filters",()->{quality.setSelection(0);language.setSelection(0);maximum.setSelection(0);ready.setChecked(false);render.run();}));
        AdapterView.OnItemSelectedListener changed=new AdapterView.OnItemSelectedListener(){public void onItemSelected(AdapterView<?> parent,View view,int position,long id){render.run();}public void onNothingSelected(AdapterView<?> parent){}};
        quality.setOnItemSelectedListener(changed);language.setOnItemSelectedListener(changed);maximum.setOnItemSelectedListener(changed);ready.setOnCheckedChangeListener((v,on)->render.run());render.run();
    });}
    Spinner filterSpinner(LinearLayout target,String label,List<String> options,String selected){target.addView(text(label,13));Spinner spinner=new Spinner(this);ArrayAdapter<String> adapter=new ArrayAdapter<>(this,android.R.layout.simple_spinner_item,options){@Override public View getView(int position,View view,ViewGroup parent){TextView row=(TextView)super.getView(position,view,parent);row.setTextColor(MainActivity.WHITE);row.setPadding(dp(12),dp(10),dp(12),dp(10));return row;}@Override public View getDropDownView(int position,View view,ViewGroup parent){TextView row=(TextView)super.getDropDownView(position,view,parent);row.setTextColor(MainActivity.WHITE);row.setBackgroundColor(MainActivity.PANEL);row.setPadding(dp(12),dp(10),dp(12),dp(10));return row;}};adapter.setDropDownViewResource(android.R.layout.simple_spinner_dropdown_item);spinner.setAdapter(adapter);spinner.setSelection(Math.max(0,options.indexOf(selected)));spinner.setBackground(MainActivity.bg(MainActivity.PANEL,dp(8)));target.addView(spinner);return spinner;}
    void appendReleases(LinearLayout target,List<JSONObject> releases,int start){for(JSONObject c:releases.subList(start,Math.min(start+20,releases.size())))target.addView(releaseCard(c));int next=start+20;if(next<releases.size()){Button more=button("Show 20 more · "+(releases.size()-next)+" remaining",()->{});more.setOnClickListener(v->{target.removeView(more);appendReleases(target,releases,next);});target.addView(more);}}
    LinearLayout releaseCard(JSONObject choice){
        LinearLayout card=new LinearLayout(this);card.setOrientation(LinearLayout.VERTICAL);card.setPadding(dp(12),dp(8),dp(12),dp(8));card.setBackground(MainActivity.bg(MainActivity.PANEL,dp(10)));
        TextView title=text(choice.optString("name"),15);title.setMaxLines(2);title.setEllipsize(android.text.TextUtils.TruncateAt.END);card.addView(title);
        String cache=choice.optString("cacheStatus").equals("Ready")?"Ready on TorBox":choice.optString("cacheStatus").equals("Not cached")?"Needs fetching":"Availability unknown";
        card.addView(text(choice.optString("resolution","Quality unknown")+" · "+choice.optString("languages","Audio unconfirmed")+(choice.optString("codec").isEmpty()?"":" · "+choice.optString("codec"))+(choice.optString("picture").isEmpty()?"":" · "+choice.optString("picture"))+" · "+choice.optString("sizeKind","Release")+": "+size(choice.optLong("size"))+" · "+cache,13));
        Button choose=button("Choose files",()->loadFiles(choice));choose.setBackground(MainActivity.bg(MainActivity.GOLD,dp(8)));choose.setTextColor(MainActivity.BLACK);card.addView(choose);
        TextView details=text(choice.optJSONArray("sources")+"\n"+choice.optString("detail")+(choice.optString("warning").isEmpty()?"":"\n"+choice.optString("warning")),12);details.setVisibility(View.GONE);
        TextView sources=text(choice.optInt("sourceEntries",1)+" source entries · details  ›",12);sources.setTextColor(MainActivity.MUTED);sources.setMinHeight(dp(48));sources.setGravity(Gravity.CENTER_VERTICAL);sources.setOnClickListener(v->details.setVisibility(details.getVisibility()==View.GONE?View.VISIBLE:View.GONE));card.addView(sources);card.addView(details);
        LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,-2);p.setMargins(0,0,0,dp(12));card.setLayoutParams(p);return card;
    }
    void loadPlan(JSONArray releases){JSONObject payload=new JSONObject();JSONArray ids=new JSONArray();for(JSONObject c:DataStore.objects(releases))ids.put(c.optString("id"));DataStore.put(payload,"releaseIds",ids);request("Verifying season coverage…",()->data.pcRequest("/v1/pc-downloads/plan/"+itemId,payload),r->{files=new JSONArray();for(JSONObject entry:DataStore.objects(r.getJSONArray("entries"))){JSONObject f=entry.getJSONObject("file");DataStore.put(f,"releaseId",entry.optString("releaseId"));DataStore.put(f,"release",entry.optString("release"));files.put(f);}releaseId="";requestId=UUID.randomUUID().toString();selectedRelease=new JSONObject();DataStore.put(selectedRelease,"name",r.optString("message")+(r.optJSONArray("missingEpisodes")!=null&&r.optJSONArray("missingEpisodes").length()>0?"\nMissing episodes: "+r.optJSONArray("missingEpisodes"):""));showFiles();});}
    void loadFiles(JSONObject choice){request("Getting TorBox's file list…",()->data.pcRequest("/v1/pc-downloads/files/"+choice.optString("id"),null),r->{selectedRelease=choice;releaseId=choice.optString("id");requestId=UUID.randomUUID().toString();files=r.getJSONArray("files");showFiles();});}
    void showFiles(){page("Review your PC download");if(selectedRelease!=null)body.addView(text(selectedRelease.optString("name"),17));Map<CheckBox,JSONObject> picks=new LinkedHashMap<>();Set<String> episodes=new HashSet<>();TextView total=text("",15);for(JSONObject f:DataStore.objects(files)){CheckBox box=new CheckBox(this);box.setTextColor(MainActivity.WHITE);box.setText(f.optString("name")+" · "+size(f.optLong("size"))+(f.optString("reason").isEmpty()?"":" · "+f.optString("reason")));box.setEnabled(f.optBoolean("selectable"));box.setChecked(f.optBoolean("selectable")&&episodes.add(f.optInt("season")+":"+f.optInt("episode")));picks.put(box,f);body.addView(box);if(f.optBoolean("mappingRequired"))body.addView(button("Match this file to an episode",()->matchFile(f)));box.setOnCheckedChangeListener((v,on)->selectedTotal(picks,total));}body.addView(total);selectedTotal(picks,total);body.addView(text("Existing and queued episodes are skipped. Your PC organizes the selected videos and downloads subtitles using its saved English / Arabic preferences.",14));body.addView(button("Download selected on PC",()->{Map<String,JSONArray> groups=new LinkedHashMap<>();for(Map.Entry<CheckBox,JSONObject> p:picks.entrySet())if(p.getKey().isChecked()){JSONObject f=p.getValue();String release=f.optString("releaseId",releaseId);if(!groups.containsKey(release))groups.put(release,new JSONArray());groups.get(release).put(f.optString("id"));}if(groups.isEmpty()){feedback.setText("Select at least one file.");return;}JSONArray selections=new JSONArray();for(Map.Entry<String,JSONArray> group:groups.entrySet()){JSONObject select=new JSONObject();DataStore.put(select,"releaseId",group.getKey());DataStore.put(select,"fileIds",group.getValue());selections.put(select);}JSONObject payload=new JSONObject();DataStore.put(payload,"requestId",requestId);DataStore.put(payload,"selections",selections);request("Sending to PC…",()->data.pcRequest("/v1/pc-downloads",payload),r->{itemId="";files=null;queue();});}));body.addView(button("Choose another release",()->{files=null;search();}));}
    void matchFile(JSONObject file){EditText number=new EditText(this);number.setInputType(android.text.InputType.TYPE_CLASS_NUMBER);new AlertDialog.Builder(this).setTitle("Episode number in this season").setMessage(file.optString("name")).setView(number).setPositiveButton("Confirm",(dialog,which)->{int episode;try{episode=Integer.parseInt(number.getText().toString());}catch(Exception e){feedback.setText("Enter an episode number.");return;}JSONObject payload=new JSONObject();DataStore.put(payload,"fileId",file.optString("id"));DataStore.put(payload,"episode",episode);request("Confirming episode match…",()->data.pcRequest("/v1/pc-downloads/match",payload),r->{for(String key:new String[]{"season","episode","selectable","existing","queued","reason","mappingRequired"})DataStore.put(file,key,r.opt(key));showFiles();});}).setNegativeButton("Cancel",null).show();}
    void selectedTotal(Map<CheckBox,JSONObject> picks,TextView label){long bytes=0;int count=0;boolean unknown=false;for(Map.Entry<CheckBox,JSONObject> p:picks.entrySet())if(p.getKey().isChecked()){count++;long n=p.getValue().optLong("size");bytes+=n;if(n<=0)unknown=true;}label.setText(count+" files · "+size(bytes)+(unknown?" + unknown sizes":""));}
    void queue(){queueMode=true;page("Downloads on your PC");queueRows.clear();queueLabels.clear();queueProgress.clear();queueStates.clear();queueActions.clear();body.addView(button("Refresh",this::loadQueue));body.addView(button("Find something new",()->startActivity(new Intent(this,DiscoverActivity.class))));try{String cache=getSharedPreferences("pc-queue",0).getString("queue","");if(!cache.isEmpty()){renderQueue(new JSONObject(cache));feedback.setText("Last known status · checking PC…");}}catch(Exception ignored){}loadQueue();}
    void loadQueue(){request(queueRows.isEmpty()?"Checking PC downloads…":"",()->data.pcRequest("/v1/pc-downloads",null),r->{getSharedPreferences("pc-queue",0).edit().putString("queue",r.toString()).apply();renderQueue(r);});}
    void renderQueue(JSONObject response)throws Exception{
        JSONArray jobs=response.getJSONArray("jobs");Set<String> present=new HashSet<>();int active=0;
        for(JSONObject job:DataStore.objects(jobs)){
            String id=job.optString("id"),state=job.optString("status");present.add(id);if(Arrays.asList("Queued","Preparing","Downloading","Subtitles").contains(state))active++;
            LinearLayout row=queueRows.get(id);if(row==null){row=new LinearLayout(this);row.setOrientation(LinearLayout.VERTICAL);row.setPadding(dp(14),dp(10),dp(14),dp(10));row.setBackground(MainActivity.bg(MainActivity.PANEL,dp(10)));LinearLayout.LayoutParams layout=new LinearLayout.LayoutParams(-1,-2);layout.setMargins(0,dp(8),0,dp(8));row.setLayoutParams(layout);row.addView(text(job.optString("name"),18));TextView label=text("",13);row.addView(label);ProgressBar bar=new ProgressBar(this,null,android.R.attr.progressBarStyleHorizontal);bar.setMax(1000);bar.setProgressTintList(android.content.res.ColorStateList.valueOf(MainActivity.GOLD));row.addView(bar,new LinearLayout.LayoutParams(-1,dp(6)));LinearLayout actions=new LinearLayout(this);actions.setOrientation(LinearLayout.VERTICAL);row.addView(actions);body.addView(row);queueRows.put(id,row);queueLabels.put(id,label);queueProgress.put(id,bar);queueActions.put(id,actions);}
            long bytes=job.optLong("bytes"),total=job.optLong("size");queueLabels.get(id).setText(state+(total>0?String.format(Locale.ROOT," · %.0f%%",bytes*100d/total):"")+" · "+(bytes==0?"0 B":size(bytes))+" / "+size(total)+"\n"+job.optString("message")+(job.optString("subtitleMessage").isEmpty()?"":"\n"+job.optString("subtitleMessage")));ProgressBar bar=queueProgress.get(id);bar.setIndeterminate(state.equals("Preparing"));bar.setProgress(total>0?(int)Math.min(1000,bytes*1000d/total):0);
            if(!state.equals(queueStates.get(id))){LinearLayout actions=queueActions.get(id);actions.removeAllViews();if(!state.equals("Completed"))for(String action:Arrays.asList("Paused","Failed","Cancelled").contains(state)?new String[]{"resume"}:new String[]{"pause","cancel"})actions.addView(button(action.substring(0,1).toUpperCase(Locale.ROOT)+action.substring(1),()->control(id,action)));queueStates.put(id,state);}
        }
        for(String removed:new ArrayList<>(queueRows.keySet()))if(!present.contains(removed)){body.removeView(queueRows.remove(removed));queueLabels.remove(removed);queueProgress.remove(removed);queueStates.remove(removed);queueActions.remove(removed);}
        feedback.setText(!response.optBoolean("configured")?"Set up TorBox in PC Settings first.":jobs.length()==0?"No downloads yet. Find a title in Discover.":active+" active · status updates automatically");
    }
    @Override protected void onResume(){super.onResume();foreground=true;queueHandler.removeCallbacks(queueTick);queueHandler.postDelayed(queueTick,5000);}
    @Override protected void onPause(){foreground=false;queueHandler.removeCallbacks(queueTick);super.onPause();}
    void control(String id,String action){JSONObject p=new JSONObject();DataStore.put(p,"id",id);DataStore.put(p,"action",action);request("Updating download…",()->data.pcRequest("/v1/pc-downloads/control",p),r->loadQueue());}
    static String size(long n){return n>=1073741824?String.format(Locale.ROOT,"%.2f GB",n/1073741824d):n>0?String.format(Locale.ROOT,"%.1f MB",n/1048576d):"Size unknown";}
    @Override public void onDestroy(){queueHandler.removeCallbacksAndMessages(null);requests.shutdownNow();super.onDestroy();}
}
